<?php

namespace App\Support;

/**
 * The Thinking Explorer's fixed vocabulary.
 *
 * The section 02 band on the About page ("why hire me") renders an
 * interactive thinking model: two thinking modes, six knowledge categories
 * with affinity to a mode, and each category's child concepts. This class is
 * the only place that vocabulary is *defined* — the public component, the
 * canvas engine and the admin editor all read it, so a rename cannot leave a
 * component behind (the same contract {@see WorkflowTaxonomy} holds for the
 * AI Workflow band).
 *
 * Operators do not edit this file: they store `thinking_*` rows against the
 * reasons section (see {@see \App\Enums\AboutItemType}), and the presenter
 * overlays them on these built-ins. Anything a stored row leaves out keeps
 * rendering from here, and any key the presenter cannot resolve degrades to
 * a safe default instead of stranding a node.
 */
class ThinkingTaxonomy
{
    /**
     * The two thinking modes, in display order.
     *
     * @return array{system_1: array{key: string, name: string, description: string}, system_2: array{key: string, name: string, description: string}}
     */
    public static function modes(): array
    {
        return [
            'system_1' => [
                'key' => 'system_1',
                'name' => 'System 1 — Fast thinking',
                'description' => 'Rapid recognition and pattern matching: the calls that arrive before the reasoning does. Signals move fast, short and constant.',
            ],
            'system_2' => [
                'key' => 'system_2',
                'name' => 'System 2 — Deep thinking',
                'description' => 'Deliberate reasoning: architecture, trade-offs, debugging under pressure. Signals travel long chains, in sequence, slower.',
            ],
        ];
    }

    /**
     * The knowledge categories the brain's clusters represent, in display
     * order. The canvas engine assigns one neural cluster per category in
     * this order, so order is geometry, not just preference.
     *
     * @return array<int, array{key: string, name: string, description: string, affinity: string, nodes: array<int, array{label: string, text: string}>}>
     */
    public static function categories(): array
    {
        return [
            [
                'key' => 'problem-solving',
                'name' => 'Problem Solving',
                'description' => 'Reproduce, isolate, fix — then ask why the failure was possible in the first place.',
                'affinity' => 'both',
                'nodes' => [
                    ['label' => 'Reproduce first', 'text' => 'A bug you cannot reproduce is a bug you cannot close; the harness comes before the fix.'],
                    ['label' => 'Smallest failing case', 'text' => 'Cut the system until the failure fits on one screen, then reason about it.'],
                    ['label' => 'Fix the class, not the ticket', 'text' => 'Every fix ships with the guardrail that would have caught the whole family.'],
                ],
            ],
            [
                'key' => 'systems-thinking',
                'name' => 'Systems Thinking',
                'description' => 'Queues, feedback loops and second-order effects — where a change lands matters more than what it changes.',
                'affinity' => 'deep',
                'nodes' => [
                    ['label' => 'Follow the queue', 'text' => 'Latency lives in queues, not in functions; find the wait before optimising the work.'],
                    ['label' => 'Feedback loops', 'text' => 'Caches, retries and alerts all feed back; design them or they will design themselves.'],
                    ['label' => 'Second-order effects', 'text' => 'Every limit you add moves behaviour somewhere else; say where before you ship.'],
                ],
            ],
            [
                'key' => 'architecture',
                'name' => 'Software Architecture',
                'description' => 'Boundaries, contracts and the decisions you can still defend in year two.',
                'affinity' => 'deep',
                'nodes' => [
                    ['label' => 'Boundaries over layers', 'text' => 'A good boundary is the one you can replace alone; layers are not boundaries.'],
                    ['label' => 'Boring data model', 'text' => 'Constraints in the schema beat cleverness in the code; the database outlives the framework.'],
                    ['label' => 'Reversible decisions', 'text' => 'Prefer the choice you can undo cheaply, and write down the ones you cannot.'],
                ],
            ],
            [
                'key' => 'debugging',
                'name' => 'Debugging & Analysis',
                'description' => 'Query plans, cache semantics, queue backpressure — the parts that fail at 3am get the most practice.',
                'affinity' => 'both',
                'nodes' => [
                    ['label' => 'Read the query plan', 'text' => 'EXPLAIN ANALYZE before the index; the database is already telling you.'],
                    ['label' => 'Measure the wait', 'text' => 'CPU-bound and IO-bound failures have opposite fixes; know which one you own.'],
                    ['label' => 'Bisect the deploy', 'text' => 'When did it last work? The diff between then and now is the shortest path to the cause.'],
                ],
            ],
            [
                'key' => 'learning',
                'name' => 'Learning & Memory',
                'description' => 'Write it down while the reasoning is still recoverable — this site is the habit, not a performance of it.',
                'affinity' => 'fast',
                'nodes' => [
                    ['label' => 'Write to remember', 'text' => 'A decision record costs twenty minutes and saves the next engineer a week.'],
                    ['label' => 'Teach the codebase', 'text' => 'Names are the comments that never rot; rename until the code explains itself.'],
                    ['label' => 'Return after the gap', 'text' => 'Read the note a month later; what survives the gap is what you actually learned.'],
                ],
            ],
            [
                'key' => 'decisions',
                'name' => 'Decision Making',
                'description' => 'Honest by default: if a feature should not exist, say so before anyone pays for it.',
                'affinity' => 'fast',
                'nodes' => [
                    ['label' => 'Default to no', 'text' => 'The most expensive consultant in the room is the one whose answer is always yes.'],
                    ['label' => 'Decide with the data you have', 'text' => 'A reversible decision made now beats a perfect one made after the deadline.'],
                    ['label' => 'Write the rerun', 'text' => 'If the decision had to be made again next week, the note is what makes that possible.'],
                ],
            ],
        ];
    }

    /**
     * Normalise a stored mode key; anything unresolvable falls back to
     * System 1 so a typo degrades instead of stranding a mode row.
     */
    public static function normalizeModeKey(?string $key): string
    {
        return array_key_exists((string) $key, self::modes()) ? (string) $key : 'system_1';
    }

    /**
     * Normalise a category's mode affinity — fast, deep, or the both that
     * covers "this is where the two systems meet".
     */
    public static function normalizeAffinity(?string $affinity): string
    {
        return in_array((string) $affinity, ['fast', 'deep', 'both'], true) ? (string) $affinity : 'both';
    }

    /**
     * Normalise a category key to a URL/slug-ish shape so stored keys cannot
     * break the Alpine state or the canvas cluster lookup.
     */
    public static function normalizeCategoryKey(?string $key, int $index): string
    {
        $slug = preg_replace('/[^a-z0-9]+/', '-', strtolower(trim((string) $key)));

        if ($slug === '' || $slug === null || $slug === '-') {
            return 'category-'.($index + 1);
        }

        return trim($slug, '-');
    }
}
